import {Queue} from "./Queue.js";
import {AbortablePromise} from "./AbortablePromise.js";

const enum RequestEntryIndex {
    accept = 0,
    reject = 1,
    settledQueue = 2
}
type RequestEntry<T> = [
    accept: (item: T) => void,
    reject: (reason?: unknown) => void,
    settledQueue?: AsyncQueue<T>
];

export type AsyncQueueOptions<T> = {
    /**
     * Minimum number of consumed entries before the internal array can be compacted.
     *
     * Compaction only occurs when at least half of the backing array has been consumed.
     *
     * Defaults to `4096`.
     */
    compactAt?: number,

    /**
     * A parent queue to also send requests to when the current queue is empty.
     *
     * When set, requests will also be registered with each queue in the parent chain.
     * The first queue to provide an item satisfies the request.
     *
     * When pushing to the queue, the item will be pushed to the current queue
     * unless `forwardPushesToParent` is set to `true`.
     */
    parent?: AsyncQueue<T>
};

/**
 * An async queue that allows you to wait for items to become available when the queue is empty.
 *
 * {@link shift} retrieves the first locally queued item, falling back to queues
 * in the parent chain (if a parent is set). If no item is available, it waits until one is pushed.
 *
 * When waiting, the request is registered with the current queue and all parent queues,
 * and the first one to provide an item satisfies the request.
 *
 * Pushing adds the item to the current queue, unless {@link forwardPushesToParent} is enabled.
 * @example
 * ```typescript
 * import {AsyncQueue} from "lifecycle-utils";
 *
 * const queue = new AsyncQueue([1]);
 *
 * queue.push(2);
 * console.log(await queue.shift()); // 1
 * console.log(await queue.shift()); // 2
 *
 * setTimeout(() => queue.push(3), 100);
 *
 * console.log(await queue.shift()); // 3
 * ```
 * @example
 * ```typescript
 * import {AsyncQueue, sleep} from "lifecycle-utils";
 *
 * const queue = new AsyncQueue([1, 2]);
 * const child = new AsyncQueue([9], {parent: queue});
 *
 * console.log(queue.length); // 2
 * console.log(child.length); // 1
 *
 * await Promise.all([
 *     child.withItem(async (item) => {
 *         console.log(item); // 9
 *         await sleep(1000);
 *     }),
 *     child.withItem(async (item) => {
 *         console.log(item); // 1
 *         await sleep(1000);
 *     })
 * ]);
 * console.log(queue.length); // 1 - [2]
 * console.log(child.length); // 2 - [9, 1]
 *
 *
 * const childPromise = child.withItem(async (item) => {
 *     console.log(item); // 9
 *     await sleep(1000);
 * });
 *
 * // drain the child and route returned items to the parent
 * child.drainToParent();
 * child.forwardPushesToParent = true;
 * console.log(queue.length); // 2 - [2, 1]
 * console.log(child.length); // 0
 *
 * await childPromise;
 * console.log(queue.length); // 3 - [2, 1, 9]
 * console.log(child.length); // 0
 * ```
 */
export class AsyncQueue<T> implements Iterable<T> {
    /** @internal */ private readonly _queue: Queue<T>;
    /** @internal */ private _requests = new Queue<RequestEntry<T>>();
    /** @internal */ private readonly _parent?: AsyncQueue<T>;
    /** @internal */ private _forwardPushesToParent: boolean = false;

    public constructor(values?: Iterable<T>, options?: AsyncQueueOptions<T>) {
        this._queue = new Queue(values, {compactAt: options?.compactAt});

        if (options?.parent != null)
            this._parent = options.parent;
    }

    /**
     * The number of values currently in the queue.
     *
     * **Time complexity:** `O(1)`.
     */
    public get length(): number {
        return this._queue.length;
    }

    /**
     * The number of pending requests waiting for values to be added to the queue.
     *
     * **Time complexity:** `O(1)`.
     */
    public get pendingRequests(): number {
        return this._requests.length;
    }

    /**
     * Whether the queue is empty.
     *
     * **Time complexity:** `O(1)`.
     */
    public get isEmpty(): boolean {
        return this._queue.isEmpty;
    }

    /**
     * The first (next) item in the queue, or `undefined` when the queue is empty.
     *
     * **Time complexity:** `O(1)`.
     */
    public get first(): T | undefined {
        return this._queue.first;
    }

    /**
     * The last item in the queue, or `undefined` when the queue is empty.
     *
     * **Time complexity:** `O(1)`.
     */
    public get last(): T | undefined {
        return this._queue.last;
    }

    /**
     * The parent queue, which can be set in the constructor options.
     */
    public get parent(): AsyncQueue<T> | undefined {
        return this._parent;
    }

    /**
     * Whether to route pushes to the parent queue.
     *
     * Only relevant when a parent queue is set.
     */
    public get forwardPushesToParent(): boolean {
        return this._forwardPushesToParent;
    }

    /**
     * Set whether to route pushes to the parent queue.
     *
     * Can only be set when a parent queue is set.
     */
    public set forwardPushesToParent(value: boolean) {
        if (value && this._parent == null) {
            console.warn("Cannot set forwardPushesToParent to true when no parent queue is set");
            return;
        }

        this._forwardPushesToParent = value;
    }

    /**
     * Adds an item to the end of the queue.
     * If there is a pending request,
     * the item is immediately delivered to the oldest pending request instead of being added to the queue.
     *
     * **Time complexity:** `O(1)` amortized. `O(h)` to traverse the parent chain.
     */
    public push(item: T): void {
        if (this._forwardPushesToParent && this._parent != null)
            return void this._parent.push(item);

        const nextRequest = this._requests.shift();
        if (nextRequest != null) {
            nextRequest[RequestEntryIndex.settledQueue] = this;
            nextRequest[RequestEntryIndex.accept](item);
        } else
            this._queue.push(item);
    }

    /**
     * Removes and returns the first (next) item in the queue, and if the queue is empty,
     * waits for an item to be added first and then returns that item.
     *
     * **Time complexity:** `O(1)` amortized without a parent, with occasional `O(n)` compaction.
     * Cancelling a pending request is `O(n)`. `O(h)` to traverse the parent chain.
     */
    public async shift(signal?: AbortSignal): Promise<T> {
        signal?.throwIfAborted();

        if (!this._queue.isEmpty)
            return this._queue.shift()!;

        let parentQueue = this._parent;
        while (parentQueue != null) {
            if (!parentQueue._queue.isEmpty)
                return parentQueue._queue.shift()!;

            parentQueue = parentQueue._parent;
        }

        if (this._parent == null)
            return new AbortablePromise<T>(signal, (accept, reject) => {
                const entry: RequestEntry<T> = [accept, reject];
                this._requests.push(entry);
                const entryIndex = this._requests.length - 1;

                return () => {
                    if (entry[RequestEntryIndex.settledQueue] === this)
                        return;

                    const requestIndex = this._requests.lastIndexOf(entry, entryIndex);
                    if (requestIndex >= 0)
                        this._requests.delete(requestIndex);
                };
            });

        return new AbortablePromise<T>(signal, (accept, reject) => {
            const entry: RequestEntry<T> = [accept, reject];

            this._requests.push(entry);
            const selfEntryIndex = this._requests.length - 1;

            const parentEntries: [queue: AsyncQueue<T>, index: number][] = [];
            let parentQueue = this._parent;
            while (parentQueue != null) {
                parentQueue._requests.push(entry);
                parentEntries.push([parentQueue, parentQueue._requests.length - 1]);
                parentQueue = parentQueue._parent;
            }

            return () => {
                if (entry[RequestEntryIndex.settledQueue] != this) {
                    const selfIndex = this._requests.lastIndexOf(entry, selfEntryIndex);
                    if (selfIndex >= 0)
                        this._requests.delete(selfIndex);
                }

                for (const [queue, index] of parentEntries) {
                    if (entry[RequestEntryIndex.settledQueue] === queue)
                        continue;

                    const parentIndex = queue._requests.lastIndexOf(entry, index);
                    if (parentIndex >= 0)
                        queue._requests.delete(parentIndex);
                }
                parentEntries.length = 0;
            };
        });
    }

    /**
     * Removes and returns the first (next) value in the queue
     * without waiting for an item to be added if the queue is empty.
     *
     * Returns `undefined` when the queue is empty.
     *
     * **Time complexity:** `O(1)` amortized without a `parent`, with occasional `O(n)` compaction.
     * `O(h)` to traverse the parent chain.
     */
    public tryShift(): T | undefined {
        if (!this._queue.isEmpty)
            return this._queue.shift();

        let parentQueue = this._parent;
        while (parentQueue != null) {
            if (!parentQueue._queue.isEmpty)
                return parentQueue._queue.shift();

            parentQueue = parentQueue._parent;
        }

        return undefined;
    }

    /**
     * Alias to {@link push}.
     *
     * **Time complexity:** `O(1)` amortized. `O(h)` to traverse the parent chain.
     */
    public enqueue(item: T): void {
        return this.push(item);
    }

    /**
     * Alias to {@link shift}.
     *
     * **Time complexity:** `O(1)` amortized without a parent, with occasional `O(n)` compaction.
     * Cancelling a pending request is `O(n)`. `O(h)` to traverse the parent chain.
     */
    public dequeue(signal?: AbortSignal): Promise<T> {
        return this.shift(signal);
    }

    /**
     * Alias to {@link tryShift}.
     *
     * **Time complexity:** `O(1)` amortized without a `parent`, with occasional `O(n)` compaction.
     * `O(h)` to traverse the parent chain.
     */
    public tryDequeue(): T | undefined {
        return this.tryShift();
    }

    /**
     * The first (next) item in the queue, or `undefined` when the queue is empty (alias to {@link first}).
     *
     * **Time complexity:** `O(1)`.
     */
    public peek(): T | undefined {
        return this._queue.peek();
    }

    /**
     * Returns the item at the given index without removing it.
     *
     * Negative indexes count backwards from the end of the queue.
     *
     * **Time complexity:** `O(1)`.
     */
    public at(index: number): T | undefined {
        return this._queue.at(index);
    }

    /**
     * Deletes values from the queue starting at `start` and ending before `end`.
     *
     * When `end` is omitted, only the value at `start` is deleted.
     * Negative indexes count backwards from the end of the queue.
     *
     * Returns the number of deleted values.
     *
     * **Time complexity:** `O(k)` when deleting from either end, where `k` is the number of deleted values,
     * and `O(n)` when deleting from the middle.
     */
    public delete(start: number, end?: number): number {
        return this._queue.delete(start, end);
    }

    /**
     * Returns the index of the first occurrence of a value in the queue, or `-1` when it is not found.
     *
     * **Time complexity:** `O(n)`.
     */
    public indexOf(item: T, fromIndex = 0): number {
        return this._queue.indexOf(item, fromIndex);
    }

    /**
     * Returns the index of the last occurrence of a value in the queue, or `-1` when it is not found.
     *
     * **Time complexity:** `O(n)`.
     */
    public lastIndexOf(item: T, fromIndex?: number): number {
        return this._queue.lastIndexOf(item, fromIndex);
    }

    /**
     * Returns an iterator over index-value pairs in the queue.
     *
     * **Time complexity:** `O(n)` for a full iteration and `O(1)` per value.
     */
    public entries(): IterableIterator<[number, T]> {
        return this._queue.entries();
    }

    /**
     * Returns an iterator over the values in the queue from first to last.
     *
     * **Time complexity:** `O(n)` for a full iteration and `O(1)` per value.
     */
    public values(): IterableIterator<T> {
        return this._queue.values();
    }

    /**
     * Returns the queue values as a new array.
     *
     * **Time complexity:** `O(n)`.
     */
    public toArray(): T[] {
        return this._queue.toArray();
    }

    /**
     * Removes all values from the queue.
     *
     * **Time complexity:** `O(1)`.
     */
    public clear(): void {
        this._queue.clear();
    }

    /**
     * If a parent queue is set, moves all items from the current queue to it.
     *
     * **Time complexity:** `O(n)`.
     */
    public drainToParent(): void {
        if (this._parent == null)
            return;

        while (!this._queue.isEmpty)
            this._parent.push(this._queue.shift()!);
    }

    /**
     * Reject all the pending requests with the given reason.
     *
     * **Time complexity:** `O(n)`, where `n` is the number of pending requests.
     */
    public rejectPendingRequests(reason?: unknown): void {
        const requests = this._requests;
        this._requests = new Queue();

        while (!requests.isEmpty) {
            const request = requests.shift()!;

            request[RequestEntryIndex.settledQueue] = this;
            request[RequestEntryIndex.reject](reason);
        }
    }

    /**
     * Returns an iterator over the values in the queue from first to last.
     *
     * **Time complexity:** `O(1)` to create the iterator, and `O(n)` for a full iteration.
     */
    public [Symbol.iterator](): IterableIterator<T> {
        return this.values();
    }

    /**
     * Run a callback with the next item in the queue, and if the queue is empty,
     * wait for an item to be added first and then run the callback with that item.
     *
     * When the callback is done, the item is enqueued again.
     *
     * The return value of the callback is returned to the caller.
     *
     * **Time complexity:** `O(1)` amortized, with occasional `O(n)` compaction. Cancelling a pending request is `O(n)`.
     */
    public async withItem<R>(callback: (item: T) => R | PromiseLike<R>): Promise<R>;
    public async withItem<R>(signal: AbortSignal | undefined, callback: (item: T) => R | PromiseLike<R>): Promise<R>;
    public async withItem<R>(
        signalOrCallback: AbortSignal | undefined | ((item: T) => R | PromiseLike<R>),
        callback?: (item: T) => R | PromiseLike<R>
    ): Promise<R> {
        if (typeof signalOrCallback === "function") {
            callback = signalOrCallback;
            signalOrCallback = undefined;
        }

        const item = await this.shift(signalOrCallback);
        try {
            return await callback!(item);
        } finally {
            this.push(item);
        }
    }

    /**
     * Get the next item in the queue, waiting for one to be added if the queue is empty.
     *
     * The item is wrapped in an {@link AsyncQueueItemLease}, which enqueues the item again when disposed.
     *
     * **Time complexity:** `O(1)` amortized, with occasional `O(n)` compaction. Cancelling a pending request is `O(n)`.
     * @example
     * ```typescript
     * import {AsyncQueue} from "lifecycle-utils";
     * const queue = new AsyncQueue<number>([42]);
     *
     * {
     *     using lease = await queue.acquire();
     *     console.log(lease.item); // 42
     *     console.log(queue.length); // 0
     * }
     *
     * console.log(queue.length); // 1
     * ```
     */
    public async acquire(signal?: AbortSignal): Promise<AsyncQueueItemLease<T>> {
        return AsyncQueueItemLease._create(this, await this.shift(signal));
    }
}

export class AsyncQueueItemLease<T> {
    /** @internal */ private _queue: null | AsyncQueue<T>;

    public readonly item: T;

    private constructor(queue: null | AsyncQueue<T>, item: T) {
        this._queue = queue;
        this.item = item;
    }

    public get disposed(): boolean {
        return this._queue == null;
    }

    public dispose(): void {
        if (this._queue == null)
            return;

        this._queue.push(this.item);
        this._queue = null;
    }

    public [Symbol.dispose]() {
        this.dispose();
    }

    /** Create a new lease for this item and mark the current lease as disposed */
    public move() {
        const newLease = new AsyncQueueItemLease(this._queue, this.item);
        this._queue = null;
        return newLease;
    }

    /** @internal */
    public static _create<T>(queue: AsyncQueue<T>, item: T) {
        return new AsyncQueueItemLease(queue, item);
    }
}
